def _create_policy_compat(
    method: t.Callable[..., GlobusHTTPResponse],
) -> t.Callable[..., GlobusHTTPResponse]:
    """
    Accept legacy positional arguments to ``create_policy`` and apply them onto the
    keyword-only signature.

    This is the previous positional signature, which is being maintained for backwards
    compatibility: ``(project_id, high_assurance, authentication_assurance_timeout,
    display_name, description)``.

    Positional use triggers a ``RemovedInV4Warning``. Passing too many positional
    arguments, or passing a value both positionally and by keyword, raises
    ``TypeError``.
    """

    positional_names = (
        "project_id",
        "high_assurance",
        "authentication_assurance_timeout",
        "display_name",
        "description",
    )

    @functools.wraps(method)
    def wrapper(
        self: AuthClient, *args: t.Any, **kwargs: t.Any
    ) -> GlobusHTTPResponse:
        if args:
            if len(args) > len(positional_names):
                raise TypeError(
                    "create_policy() accepts at most "
                    f"{len(positional_names)} positional arguments, but "
                    f"{len(args)} were given"
                )
            for name, value in zip(positional_names, args):
                if name in kwargs:
                    raise TypeError(
                        "create_policy() got multiple values for argument "
                        f"{name!r}"
                    )
                kwargs[name] = value
            exc.warn_deprecated(
                "Passing arguments to create_policy() positionally is deprecated. "
                "All arguments must be passed by keyword.",
            )
        return method(self, **kwargs)

    return wrapper


